SELECT CASE WHEN budget >= 3464000 THEN 'high' WHEN budget >= 959000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget, COUNT(*) AS cnt, SUM(SUM(budget)) OVER (ORDER BY CASE WHEN budget >= 3464000 THEN 'high' WHEN budget >= 959000 THEN 'mid' ELSE 'low' END) AS cumulative_budget FROM departments GROUP BY CASE WHEN budget >= 3464000 THEN 'high' WHEN budget >= 959000 THEN 'mid' ELSE 'low' END
